-- 重置所有内容, 适合在一个模块开始前被调用
function RoleControllerLoader.ResetAll() 
    RoleControllerLoader.ClearLoaders() 
    ---
    local GlobalsInDreamSpace = CS.DreamSpace.GlobalsInDreamSpace
    GlobalsInDreamSpace.DestroyInstance()
end


-- 仅仅释放 loaders, 可以在 角色控制器装配完毕后调用
function RoleControllerLoader.ClearLoaders() 
    for _,loader in pairs(_loaders) do
        if isNotNull(loader) then
            loader:Release()
        end
    end
    _loaders = {}
end


-- 先开始加载 角色控制器 关联的资源 
---@param loadPaths_ table @ 元素类型: string 
function RoleControllerLoader.RegistLoadPaths( loadPaths_ )
    loadPaths_ = checkTable(loadPaths_)
    for _,path in pairs(loadPaths_) do 
        if type(path) == "string" and not string.isEmpty(path) then 

            if isNull( _loaders[path] ) then 
                _loaders[path] = ResourceModule.LoadBundleAsync(path, nil, true)
            end 
        end 
    end 
end


---@param loadPaths_ table @ 元素类型: string 
function RoleControllerLoader.IsTargetLoadingFinish( loadPaths_ ) 
    loadPaths_ = checkTable(loadPaths_)
    for _,path in pairs(loadPaths_) do 
        if type(path) == "string" and not string.isEmpty(path) then 

            if isNotNull( _loaders[path] ) then 
                if _loaders[path].IsSuccess == false then 
                    return false 
                end 
            else 
                printError("没找到目标 load: " .. tostring(path) )
                return false 
            end
        end 
    end 
    return true
end



function RoleControllerLoader.IsAllLoadingFinish()
    for name,loader in pairs(_loaders) do 
        if loader.IsSuccess == false then 
            return false 
        end 
    end 
    return true
end



-- 正式装配一个 角色控制器:
-- [协程调用]:
-- params 的内容:
-- {
--      switchablePlayerPrefabPath      -- 如: "DreamSpace/Gameplay/SwitchablePlayeForLua.prefab"
--      humanPrefabPath,                -- 如: "Arts/Prefab_human/103008_human.prefab"  -- 允许为 nil
--      ---
--      initPos,                -- 角色初始 pos
--      initRoleDir,            -- 角色初始 朝向
--      initLookDir,            -- 第三人称跟随相机的初始观察方向
--      initHumanScale,          -- 角色缩放比例 (人形态)  注意: 这个值不会去主动改写 角色碰撞体的尺寸; 对此参考下方的 humanCapsuleRadius 系列参数
--      ---
--      ---                     人形态 KinematicCharacterMotor 的 capsule 碰撞体参数;
--      humanCapsuleRadius,         -- (可为 nil)
--      humanCapsuleHeight,         -- (可为 nil)
--      humanCapsuleYOffset         -- (可为 nil)
--      ---
--      ---                     猫形态的相机参数:
--      vcamHeight_Cat,             -- (可为 nil)
--      vcamRadius_Cat,             -- (可为 nil)
--      vcamShoulderOffset_Cat,     -- (可为 nil)
--      ---                     人形态的相机参数:
--      vcamHeight_Human,           -- (可为 nil)
--      vcamRadius_Human,           -- (可为 nil)
--      vcamShoulderOffset_Human,   -- (可为 nil)
--      --- 
--      ---                     相机俯仰角(角度) 上下界: -- !! 未来可拓展下, 拆分为 人/猫 两份:
--      pitchMinDegree              -- 下界; 默认 -10
--      pitchMaxDegree              -- 上界; 默认  80
--      ---
--      isCat,
--      isUseManualViwRotateInPCMode                -- (可为 nil)  在 pc平台, 是否启用 移动端风格的相机旋转 (就是用鼠标去主动滑动屏幕来实现旋转); 启用后会主动设置 CursorLockMode.None 显示鼠标
--      isIgnoreRunStop,                            -- (可为 nil)  是否禁用 "跑停" 动画,
--      isIgnoreJumpHint,                           -- (可为 nil)  屏蔽 cat jump hint 功能
--      isIgnoreHuman180TurnBack                    -- (可为 nil)  屏蔽人形态 180大转身动画
--      isUsePiecesCollector                        -- (可为 nil)  启用 情绪碎片收集功能
--      isUseAltKey                                 -- (可为 nil)  是否支持 alt 组合键
--      isHumanNeedCustomLightDirRelativeCamera     -- (可为 nil)  是否要为 human 添加 CustomLightDirRelativeCamera 组件
--      isHideCat                                   -- (可为 nil)  是否要隐藏猫, 默认 false
--      isHideFootStep                              -- (可为 nil)  是否要隐藏脚印, 默认 false
--      isHideLeftJoystick                          -- (可为 nil)  是否主动隐藏 左摇杆按钮ui; 默认 false; 本来此ui只在 移动端显示, 通过设置本开关可强制在移动端也隐藏此ui;  (仅在初始化时隐藏, 后续运行时可通过代码开启)
-- }
function RoleControllerLoader.AssembleRole( params, returnTable_ ) 
    ---
    params = checkTable(params)

    if type(params.switchablePlayerPrefabPath) ~= "string" or string.isEmpty(params.switchablePlayerPrefabPath) then 
        --print("使用默认的 switchablePlayerPrefabPath")
        --params.switchablePlayerPrefabPath = defaultSwitchablePlayerPrefabPath
        printError("必须设置 params.switchablePlayerPrefabPath")
        return
    end 

    if type(params.humanPrefabPath) ~= "string" or string.isEmpty(params.humanPrefabPath) then 
        params.humanPrefabPath = nil
    end 

    if isNull(params.initPos)  then 
        params.initPos = Vector3.zero
    end 

    if isNull(params.initRoleDir)  then 
        params.initRoleDir = Vector3( 0, 0, 1 )
    end 
    params.initRoleDir = Vector3.ProjectOnPlane( params.initRoleDir, Vector3.up )

    if isNull(params.initLookDir)  then 
        params.initLookDir = Vector3( 0, 0, 1 )
    end 

    if isNull(params.initHumanScale)  then 
        params.initHumanScale = Vector3.one
    end 
    ---
    if type(params.vcamHeight_Cat) ~= "number"  then 
        params.vcamHeight_Cat = 0.25
    end 
    if type(params.vcamRadius_Cat) ~= "number"  then 
        params.vcamRadius_Cat = 2.7
    end 
    if isNull(params.vcamShoulderOffset_Cat) then 
        params.vcamShoulderOffset_Cat = Vector3.zero
    end 
    ---
    if type(params.vcamHeight_Human) ~= "number"  then 
        params.vcamHeight_Human = 1
    end 
    if type(params.vcamRadius_Human) ~= "number"  then 
        params.vcamRadius_Human = 4.5
    end 
    if isNull(params.vcamShoulderOffset_Human) then 
        params.vcamShoulderOffset_Human = Vector3.zero
    end 
    ---
    if isNull(params.pitchMinDegree) then 
        params.pitchMinDegree = -10
    end 
    if isNull(params.pitchMaxDegree) then 
        params.pitchMaxDegree = 80
    end 
    ---
    if      type(params.humanCapsuleRadius) == "number"
        or  type(params.humanCapsuleHeight) == "number"
        or  type(params.humanCapsuleYOffset) == "number"
    then 
        if type(params.humanCapsuleRadius) ~= "number"  then 
            params.humanCapsuleRadius = 0.5
        end 
        if type(params.humanCapsuleHeight) ~= "number"  then 
            params.humanCapsuleHeight = 2
        end 
        if type(params.humanCapsuleYOffset) ~= "number"  then 
            params.humanCapsuleYOffset = 1
        end
    end 
    --- 
    if type(params.isUseManualViwRotateInPCMode) ~= "boolean"  then 
        params.isUseManualViwRotateInPCMode = false
    end 
    if type(params.isIgnoreRunStop) ~= "boolean"  then 
        params.isIgnoreRunStop = false
    end 
    if type(params.isIgnoreJumpHint) ~= "boolean"  then 
        params.isIgnoreJumpHint = false
    end 
    if type(params.isIgnoreHuman180TurnBack) ~= "boolean"  then 
        params.isIgnoreHuman180TurnBack = false
    end 
    if type(params.isUsePiecesCollector) ~= "boolean"  then 
        params.isUsePiecesCollector = false
    end 
    if type(params.isUseAltKey) ~= "boolean"  then 
        params.isUseAltKey = false
    end
    if type(params.isHumanNeedCustomLightDirRelativeCamera) ~= "boolean"  then 
        params.isHumanNeedCustomLightDirRelativeCamera = false
    end 
    if type(params.isHideCat) ~= "boolean"  then 
        params.isHideCat = false
    end 
    if type(params.isHideFootStep) ~= "boolean"  then 
        params.isHideFootStep = false
    end 
    if type(params.isHideLeftJoystick) ~= "boolean"  then 
        params.isHideLeftJoystick = false
    end 
    ---  
    if type(params.isCat) ~= "boolean"  then 
        params.isCat = true
    end 
    params.initMorphologyType = (params.isCat==true) and RoleMorphologyType.Cat or RoleMorphologyType.Human


    -- ===============================================
    while not RoleControllerLoader.IsAllLoadingFinish() do
        coroutine.yield(Yielders.EndOfFrame)
    end

    ---
    local _switchablePlayerTF   = RoleControllerLoader._Instance(params.switchablePlayerPrefabPath)
    if isNull(_switchablePlayerTF) then 
        printError("没得到 _switchablePlayerTF")
        return
    end 
    _switchablePlayerTF.position = Vector3.zero
    _switchablePlayerTF.rotation = Quaternion.identity
    
    local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
    local vo = MaidCoffeeUtils.GetMaidCoffeeSettingVo()
    local sceneInstance = SceneManagement:GetInstance():GetSceneInstance(vo.sceneId)
    if sceneInstance then
        sceneInstance:AddCacheObject(_switchablePlayerTF.gameObject)
    end
    -- =================================== Human =========================================
    if isNotNull(params.humanPrefabPath) then 
        local _humanRootTF = RoleControllerLoader._Instance(params.humanPrefabPath)
        if isNull(_humanRootTF) then 
            printError("没得到 _humanRootTF")
            return
        end 
        local humanAnimatorTF = DreamSpaceLuaUtils.FindFirstChildByComponent( _humanRootTF, typeof(RootMotion) )
        assert(isNotNull(humanAnimatorTF))

        _humanRootTF.name = "Human"
        KTool.SetParent( _humanRootTF.gameObject, _switchablePlayerTF.gameObject )
        _humanRootTF.position = params.initPos
        _humanRootTF.rotation = Quaternion.identity

        -- 人形态的 模型比例 和 capsule 碰撞体尺寸:
        if isNotNull(params.initHumanScale) then 
            humanAnimatorTF.localScale = params.initHumanScale
        end 

        if type(params.humanCapsuleRadius) == "number" then
            local kcMotor = KTool.GetComponent(_humanRootTF.gameObject, typeof(KinematicCharacterMotor))
            kcMotor:SetCapsuleDimensions( params.humanCapsuleRadius, params.humanCapsuleHeight, params.humanCapsuleYOffset )
        end

        if params.isHumanNeedCustomLightDirRelativeCamera == true then 
            KTool.GetOrAddComponent(humanAnimatorTF.gameObject,typeof(CS.CustomLightDirRelativeCamera))
        end 

        -- if params.isIgnoreHuman180TurnBack == true then 
        --     --- 关闭角色的 180大转身动画:
        --     Events.Broadcast(DreamSpaceStates.EventNames.SetHumanHasTurnBack, false)
        -- end 

        params.humanRootTF = _humanRootTF 
        params.humanAnimatorTF = humanAnimatorTF

    else 
        params.humanRootTF = nil 
        params.humanAnimatorTF = nil
    end


    -- =================================== Cat =========================================
    local _CatTF = _switchablePlayerTF:Find("Cat")
    if isNull(_CatTF) then 
        printError("没得到 _CatTF")
        return
    end 

    _CatTF.position = params.initPos

    local catAnimatorTF = DreamSpaceLuaUtils.FindFirstChildByComponent( _CatTF, typeof(RootMotion) )
    assert(isNotNull(catAnimatorTF))

    -- 隐藏猫的显示: (一个为了支持外部模块而存在的功能)
    if params.isHideCat == true then 
        local geometryTF = catAnimatorTF:Find("Unity_Export_Grp/Geometry")
        if isNotNull(geometryTF) then 
            CfUtils.SetActive( geometryTF.gameObject, false )
        else 
            printError("没找到 Unity_Export_Grp/Geometry")
        end 
    end 



    -- ============================================================================
    local createPlayerTF = _switchablePlayerTF:Find("CreatePlayer")
    local createPlayerComp = DreamSpaceLuaUtils.GetLuaScr(createPlayerTF.gameObject, "Game.DreamSpace.CharacterController.CreatePlayer" )
    assert( createPlayerComp )

    -- ! 等一帧来确保 PMAnimator, AnimationAdapter 实例执行完自己的 Start(); 在单lua场景测试中遇到此问题
    coroutine.yield(Yielders.EndOfFrame) 
    createPlayerComp:Init( params ) 


    -- 等待 角色控制器 初始化完成:
    while DreamSpaceStates.isRoleControllerInited == false do 
        coroutine.yield(Yielders.EndOfFrame)
        --print("--1-- 等")
    end 

    
    DreamSpaceStates.isUseAltKey = (params.isUseAltKey == true)


    -- 等待 角色控制器 初始化完成:
    -- while DreamSpaceStates.isRoleControllerInited == false do 
    --     coroutine.yield(Yielders.EndOfFrame)
    -- end 

    -- =========== 返回值 ============
    if isTable(returnTable_) then 
        returnTable_.humanRootTF = params.humanRootTF -- 可能为 nil
        returnTable_.vCam3rdPersonFollowController = createPlayerComp.vcam3rdPersonFollowControllerEnv 
    end
end




function RoleControllerLoader._Instance( loaderKey_ ) 
    local loader = _loaders[loaderKey_]
    if isNotNull(loader) and loader.IsSuccess==true then 
        local newgo = loader:Instantiate()
        return newgo.transform      
    else 
        printError("koko - prefab 异步加载失败: " .. tostring(loaderKey_) )
        return nil
    end
end 




return RoleControllerLoader